alter table public.products add column if not exists features text not null default '';
update public.products set name='Anna Rosemary Hair Oil', description='A premium botanical hair oil thoughtfully formulated to nourish the scalp and condition the hair. Enriched with rosemary, it supports a healthy-looking scalp while leaving the hair feeling soft, smooth, and beautifully cared for. An elegant addition to your daily hair-care ritual.', features=E'Scalp care: Nourishes for a healthy-looking scalp\nSoft finish: Leaves hair soft and smooth\nDaily ritual: An elegant hair-care step' where slug='rosemary-hair-oil';
update public.products set name='Anna Black Seed Hair Oil', description='A premium botanical hair oil inspired by the traditional beauty use of black seed. Carefully formulated to nourish and condition the scalp and hair, it helps maintain soft, moisturized, healthy-looking hair. Perfect for elevating your natural hair-care ritual.', features=E'Heritage: Inspired by traditional black seed care\nConditioning: Nourishes scalp and hair\nMoisture: Keeps hair soft and moisturized' where slug='black-seed-hair-oil';
update public.products set name='Anna Castor Hair Oil', description='A rich and luxurious hair oil designed to deeply condition dry-feeling hair and nourish the scalp. Its naturally rich texture helps leave the hair feeling softer, smoother, more manageable, and beautifully conditioned.', features=E'Deep conditioning: Cares for dry-feeling hair\nRich texture: Naturally rich and nourishing\nManageable: Softer, smoother hair' where slug='castor-oil';
update public.products set name='Anna Frankincense Facial Oil', description='A luxurious botanical facial oil inspired by the timeless beauty tradition of frankincense. Carefully selected for its nourishing and conditioning qualities, it helps leave the skin feeling soft, smooth, supple, and beautifully moisturized. A refined addition to a premium skincare ritual.', features=E'Timeless tradition: Inspired by frankincense beauty care\nNourishing: Conditions and moisturizes skin\nSupple feel: Leaves skin soft and smooth' where slug='frankincense-essential-oil';
update public.products set name='Anna Myrrh Facial Oil', description='A luxurious botanical facial oil inspired by the rich heritage of myrrh in traditional beauty care. Designed to nourish and condition the skin, it leaves the complexion feeling soft, smooth, and well moisturized while bringing a naturally elegant touch to your skincare routine.', features=E'Rich heritage: Rooted in traditional myrrh care\nConditioning: Nourishes the complexion\nElegant touch: Soft, well-moisturized skin' where slug='myrrh-essential-oil';